css:
.lt-root{position:absolute;left:64px;bottom:72px;display:flex;align-items:flex-end;font-family:var(--lt-font);}
.lt-avatar{width:var(--lt-avatar-size);height:var(--lt-avatar-size);overflow:hidden;background:#0c0c0d;border:1px solid #3a3a3f;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.lt-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.lt-avatar img.is-ready{display:block;}
.lt-avatar-fallback{color:#6b6b64;font-size:34px;font-weight:700;line-height:1;}
.lt-avatar:has(img.is-ready) .lt-avatar-fallback{display:none;}
.lt-panel{position:relative;background:rgba(10,10,11,.94);padding:13px 40px 14px 18px;min-width:320px;border-top:1px solid rgba(255,255,255,.08);}
.lt-bar{position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--lt-accent);}
.lt-name{color:#f2f2ee;font-size:var(--lt-name-size);font-weight:700;letter-spacing:.5px;line-height:1.14;white-space:nowrap;}
.lt-sub{color:#b9b9b2;font-size:var(--lt-sub-size);font-weight:400;line-height:1.35;margin-top:3px;white-space:nowrap;min-height:1.35em;}
.lt-sub:empty{display:none;}
.lt-team{display:flex;align-items:center;gap:8px;margin-bottom:3px;}
.lt-team:not(:has(.lt-team-name:not(:empty),img.is-ready)){display:none;}
.lt-team-logo{position:relative;width:var(--lt-team-logo);height:var(--lt-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.lt-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.lt-team-logo img.is-ready{display:block;}
.lt-team-fallback{width:6px;height:6px;background:var(--lt-accent);}
.lt-team-logo:has(img.is-ready) .lt-team-fallback{display:none;}
.lt-team-name{color:var(--lt-accent);font-size:var(--lt-team-size);font-weight:700;letter-spacing:1.5px;line-height:1.2;white-space:nowrap;max-width:420px;overflow:hidden;text-overflow:ellipsis;}
.lt-team-name:empty{display:none;}
